import json

def flipH(grid):
    return [row[::-1] for row in grid]

def transpose(grid):
    return [list(col) for col in zip(*grid)]

def flipV(grid):
    return grid[::-1]

def rotate180(grid):
    return [row[::-1] for row in grid[::-1]]

def transform(grid):
    n = len(grid)
    TL = grid
    TR = flipH(transpose(grid))
    BL = flipV(transpose(grid))
    BR = rotate180(grid)

    pred = []
    for i in range(n):
        pred.append(TL[i] + TR[i])
    for i in range(n):
        pred.append(BL[i] + BR[i])
    return pred
